head.script:
scwin.screenId = "jldfil10601";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil10601.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.esgEditorUrl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.esgEditorUrl = function () {
    /* sdd-asis-lifecycle:begin esgEditorUrl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var url = "https://dev-editor.krx.co.kr/editor/login?hash=";
    if (location.hostname === 'idev-filing.krx.co.kr') {
        url = "https://idev-editor.krx.co.kr/editor/login?hash=";
    }
    var url = "https://test-editor.krx.co.kr/editor/login?hash=";
    if (location.hostname === 'itest2-filing.krx.co.kr') {
        url = "https://itest2-editor.krx.co.kr/editor/login?hash=";
    }
    if (location.hostname === 'test2-filing.krx.co.kr') {
        url = "https://test2-editor.krx.co.kr/editor/login?hash=";
    }
    var url = "https://editor.krx.co.kr/editor/login?hash=";
    var url = "https://dr-editor.krx.co.kr/editor/login?hash=";
    return url;
    /* sdd-asis-lifecycle:end */
};
